function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*799999+83);var models=['m-alpha','m-beta','m-gamma','m-delta','m-eps','m-zeta'];var caps=['search','reason','code','retrieve','verify','simulate','plan','explain'];var pairs=[];models.forEach(function(m){caps.forEach(function(c){pairs.push({model:m,capability:c,contribution:+(R()).toFixed(2)});});});pairs.sort(function(a,b){return b.contribution-a.contribution;});var strong=pairs.filter(function(p){return p.contribution>0.7;}).length;return{models:models.length,capabilities:caps.length,top3_pairings:pairs.slice(0,3),strong_pairings:strong,matrix_density_pct:+(strong/pairs.length*100).toFixed(1)};}
var SEED = 99001;
console.log(JSON.stringify(demoRun(SEED), null, 1));

